/** Only messages generated by the BOOMBOX website quotation form can enter this flow. */
export type IncomingQuoteMail = { id: string; subject: string; from: string; body: string };
const heading = /^NUEVA COTIZACI[ÓO]N BOOMBOX$/i;
const required = [/^nombre\s*:/im, /^(?:correo|email)\s*:/im, /^tipo\s*(?:de\s*)?evento\s*:/im, /^fecha\s*:/im];

export function isBoomboxWixQuoteMail(mail: IncomingQuoteMail, allowedSenders: readonly string[]) {
  const from = mail.from.match(/<([^<>]+)>/)?.[1] ?? mail.from;
  if (!allowedSenders.some(email => email.toLowerCase() === from.trim().toLowerCase())) return false;
  if (!heading.test(mail.subject.trim())) return false;
  const lines = mail.body.replace(/\r\n?/g, "\n").split("\n");
  if (!lines.some(line => heading.test(line.trim()))) return false;
  return required.every(pattern => pattern.test(mail.body));
}
